 function neighbors(graph,id){const found=new Map();for(const edge of graph.edges){if(edge.from!==id&&edge.to!==id)continue;const target=edge.from===id?edge.to:edge.from,node=graph.nodes.find(n=>n.id===target);if(!node)continue;if(!found.has(target))found.set(target,{edge,node,edges:[]});found.get(target).edges.push(edge);}return [...found.values()];}
